    'f255d435cc381419dd86f47264d1c0209f97b6247e01cc264bb21f1218cc5826':
      "import { Plugin } from '@opencode/plugin';\nexport default Plugin.define({\n  id: " +
      "'context-kit.continuity',\n\n  async setup(ctx) {\n    await ctx.session.hook('context', " +
      "(event) => {\n      event.system.push({\n        type: 'text',\n        text: 'Keep the " +
      'latest goal, required constraints, source anchors and acceptance checks explicit. ' +
      "Verify the artifact against the goal.',\n      });\n    });\n    await " +
      "ctx.session.hook('compaction', (event) => {\n      event.system.push({\n        type: " +
      "'text',\n        text:\n          'Preserve the latest goal, constraints, source anchors, " +
      "decisions, open work and ' +\n          'verification status. Reload required facts " +
      "after compaction.',\n      });\n    });\n  },\n});\n",
